/**
 * PAGES D'EXEMPLE (18/11, piste D de l'accueil) — un compte sans page peut
 * en créer une d'un clic, pour vivre le parcours du LECTEUR avant même
 * d'avoir un artefact sous la main.
 *
 * Chaque exemple est construit pour faire jouer TOUTES les fonctions :
 * une page autonome (aucun script ni police externes : elle passe derrière
 * les filtres d'entreprise), interactive (une page Getgents n'est pas un
 * PDF), sans coordonnées (l'alerte « données personnelles » ne doit pas
 * partir au premier essai), et une QUESTION PIÈGE dont la page ne dit
 * volontairement rien : l'assistant répond « la page ne le dit pas », et
 * l'auteur découvre les précisions en y répondant.
 *
 * L'univers graphique s'éloigne exprès de celui de Claude (crème, serif) :
 * la page appartient à son auteur, pas à un assistant.
 *
 * Module PUR. Les contenus sont générés depuis les maquettes validées —
 * les modifier ici, puis relire au navigateur.
 */

export type IdExemple = "proposition" | "devis" | "comite" | "weekend" | "cv";

/** Les publics de la question d'accueil « Avec qui voulez-vous partager ? ». */
export type Public = "clients" | "equipe" | "proches" | "recruteur";

export interface ExemplePage {
  id: IdExemple;
  titre: string;
  /** Une ligne pour la carte de l'accueil. */
  resume: string;
  contenu: string;
  /** Questions suggérées aux lecteurs ; la DERNIÈRE est la question piège. */
  suggestions: string[];
  questionPiege: string;
  /** Le public de l'accueil auquel l'exemple est proposé en premier. */
  public: Public;
  /** Bouton d'engagement posé à la création (fait découvrir la réponse du lecteur). */
  engagement?: string;
  /** Ce que le modèle fait découvrir, en pastilles (rubrique « Modèles »). */
  atouts: string[];
  /** Nom court, en minuscules (« 4 autres modèles : devis, … »). */
  court: string;
}

/** Préfixe de `pages.origine` d'une page d'exemple (colonne libre, aucune migration). */
export const ORIGINE_EXEMPLE = "exemple:";

export const origineExemple = (id: IdExemple) => `${ORIGINE_EXEMPLE}${id}`;

export function exempleDeOrigine(origine: string | null | undefined): ExemplePage | null {
  if (!origine?.startsWith(ORIGINE_EXEMPLE)) return null;
  return EXEMPLES.find((e) => e.id === origine.slice(ORIGINE_EXEMPLE.length)) ?? null;
}

